#[tokio::test]
async fn resource_and_drop_without_shutdown() {
    let config = local("res")
        .with_service_version("2.0")
        .with_environment("ci");
    let resource = build_resource(&config);
    let get = |k: &'static str| {
        resource
            .get(&opentelemetry::Key::from_static_str(k))
            .map(|v| v.to_string())
    };
    assert_eq!(get("service.name").as_deref(), Some("res"));
    assert_eq!(get("service.version").as_deref(), Some("2.0"));
    assert_eq!(get("deployment.environment").as_deref(), Some("ci"));
    assert_eq!(get("deployment.environment.name").as_deref(), Some("ci"));

    let exp = MemorySpanExporter::new();
    assert_eq!(exp.service_name(), "unknown_service");
    let handle = exp.init(config).unwrap();
    let clone = handle.clone();
    drop(handle);
    span_in(&clone, "kept", vec![]).await;
    clone.force_flush(None).await.unwrap();
    let provider = clone.tracer_provider();
    drop(clone); // last handle: shutdown happens on a helper thread
    for _ in 0..200 {
        if exp.shutdown_calls() == 1 {
            break;
        }
        tokio::time::sleep(Duration::from_millis(5)).await;
    }
    assert_eq!(exp.shutdown_calls(), 1);
    drop(provider);
}

