fn b3_single_and_multi() {
    let single = B3Propagator::single();
    let multi = B3Propagator::multi();
    assert_eq!(single.fields().collect::<Vec<_>>(), ["b3"]);
    assert_eq!(multi.fields().count(), 4);
    let cx = Context::new().with_remote_span_context(sc(true));
    let mut c = HashMap::new();
    single.inject_context(&cx, &mut c);
    assert_eq!(
        c["b3"],
        "4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-1"
    );
    let mut m = HashMap::new();
    multi.inject_context(&Context::new().with_remote_span_context(sc(false)), &mut m);
    assert_eq!(m["x-b3-sampled"], "0");
    let mut none = HashMap::new();
    single.inject_context(&Context::new(), &mut none);
    assert!(none.is_empty());

    let extract = |pairs: &[(&str, &str)]| {
        let map: HashMap<String, String> = pairs
            .iter()
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect();
        let cx = single.extract_with_context(&Context::new(), &map);
        let sc = cx.span().span_context().clone();
        sc.is_valid().then(|| {
            (
                sc.trace_id().to_string(),
                sc.span_id().to_string(),
                sc.is_sampled(),
            )
        })
    };
    let full = "4bf92f3577b34da6a3ce929d0e0e4736".to_string();
    let span = "00f067aa0ba902b7".to_string();
    assert_eq!(
        extract(&[("b3", &format!("{full}-{span}-1"))]),
        Some((full.clone(), span.clone(), true))
    );
    assert_eq!(
        extract(&[("b3", &format!("{full}-{span}-0"))]),
        Some((full.clone(), span.clone(), false))
    );
    assert!(
        extract(&[("b3", &format!("{full}-{span}-d-1234"))])
            .unwrap()
            .2
    );
    assert!(
        extract(&[("b3", &format!("{full}-{span}"))]).unwrap().2,
        "deferred = sampled"
    );
    assert_eq!(
        extract(&[("b3", &format!("a3ce929d0e0e4736-{span}-1"))])
            .unwrap()
            .0,
        "0000000000000000a3ce929d0e0e4736"
    );
    assert_eq!(extract(&[("b3", "0")]), None);
    assert_eq!(extract(&[("b3", &format!("zz-{span}"))]), None);
    assert_eq!(
        extract(&[("b3", &format!("{full}-0000000000000000"))]),
        None
    );
    assert_eq!(
        extract(&[("b3", &format!("{}-{span}", "0".repeat(32)))]),
        None
    );
    assert_eq!(extract(&[("b3", &format!("{full}-{span}x"))]), None);
    assert_eq!(
        extract(&[
            ("x-b3-traceid", &full),
            ("x-b3-spanid", &span),
            ("x-b3-sampled", "true")
        ]),
        Some((full.clone(), span.clone(), true))
    );
    assert!(
        extract(&[
            ("x-b3-traceid", &full),
            ("x-b3-spanid", &span),
            ("x-b3-sampled", "0"),
            ("x-b3-flags", "1")
        ])
        .unwrap()
        .2,
        "debug flag forces sampling"
    );
    assert_eq!(extract(&[("x-b3-traceid", &full)]), None);
    assert_eq!(extract(&[]), None);

    let composite = build_propagator(
        &[
            PropagatorKind::TraceContext,
            PropagatorKind::Baggage,
            PropagatorKind::B3,
            PropagatorKind::B3Multi,
        ],
        HashMap::new(),
    )
    .unwrap();
    let mut all = HashMap::new();
    composite.inject_context(&cx, &mut all);
    assert!(
        all.contains_key("traceparent")
            && all.contains_key("b3")
            && all.contains_key("x-b3-traceid")
    );
}

#[tokio::test]
async fn otlp_exporter_factory() {
    for protocol in [Protocol::HttpProtobuf, Protocol::Grpc] {
        for compression in [Compression::Gzip, Compression::None] {
            let config = local("otlp")
                .with_protocol(protocol)
                .with_compression(compression)
                .with_endpoint("http://127.0.0.1:4318")
                .with_header("x-tenant", "t1");
            assert!(
                otlp_exporter(&config).is_ok(),
                "{protocol:?} {compression:?}"
            );
        }
    }
    assert!(otlp_exporter(&local("otlp").with_endpoint("http://h:4318/v1/traces/")).is_ok());
    assert!(otlp_exporter(&local("otlp")).is_ok());
    assert!(otlp_exporter(&local("otlp").with_protocol(Protocol::Grpc)).is_ok());
    let err = otlp_exporter(&local("n").with_protocol(Protocol::Native)).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Config);
    for (k, v) in [("bad header", "v"), ("x-ok", "bad\nvalue")] {
        let c = local("g").with_protocol(Protocol::Grpc).with_header(k, v);
        assert_eq!(otlp_exporter(&c).unwrap_err().code(), ErrorCode::Config);
    }
    let err = otlp_exporter(&local("h").with_endpoint("http://[::1")).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Config);
    // Endpoints with a path are kept; bare endpoints get /v1/traces.
    for (given, want) in [
        ("http://c:4318", "http://c:4318/v1/traces"),
        ("http://c:4318/", "http://c:4318/v1/traces"),
        (
            "https://h/api/default/v1/traces",
            "https://h/api/default/v1/traces",
        ),
        ("https://h/otlp", "https://h/otlp"),
        ("http://c:4318/v1/traces/", "http://c:4318/v1/traces"),
        ("https://h/otlp/", "https://h/otlp"),
        ("http://c:4318/?a=1", "http://c:4318/?a=1"),
        ("not a url", "not a url"),
    ] {
        assert_eq!(http_traces_endpoint(given), want, "{given}");
    }
    assert!(otlp_exporter(&local("p").with_endpoint("https://h/api/default/v1/traces")).is_ok());

    // TLS settings apply to the HTTP client and (feature `otlp-tls`) to gRPC.
    let fixtures = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures");
    let tls = TlsConfig {
        ca_cert_path: Some(format!("{fixtures}/ca.pem").into()),
        ca_cert_pem: Some(std::fs::read_to_string(format!("{fixtures}/ca.pem")).unwrap()),
        client_cert_path: Some(format!("{fixtures}/client.pem").into()),
        client_key_path: Some(format!("{fixtures}/client.key").into()),
        insecure_skip_verify: false,
    };
    let https = local("tls")
        .with_endpoint("https://collector:4318")
        .with_tls(tls.clone());
    assert!(otlp_exporter(&https).is_ok());
    let insecure = TlsConfig {
        insecure_skip_verify: true,
        ..TlsConfig::default()
    };
    assert!(otlp_exporter(&https.clone().with_tls(insecure.clone())).is_ok());
    let missing = TlsConfig {
        ca_cert_path: Some("/nonexistent/ca.pem".into()),
        ..TlsConfig::default()
    };
    assert_eq!(
        otlp_exporter(&https.clone().with_tls(missing.clone()))
            .unwrap_err()
            .code(),
        ErrorCode::Config
    );
    // A default TlsConfig is ignored.
    assert!(otlp_exporter(&local("t").with_tls(TlsConfig::default())).is_ok());
    let grpc = local("g")
        .with_protocol(Protocol::Grpc)
        .with_endpoint("https://collector:4317");
    // plaintext gRPC endpoints never use TLS settings
    let plain = local("g")
        .with_protocol(Protocol::Grpc)
        .with_endpoint("http://collector:4317");
    assert!(otlp_exporter(&plain.clone().with_tls(insecure.clone())).is_ok());
    {
        if cfg!(feature = "otlp-tls") {
            assert!(otlp_exporter(&grpc.clone().with_tls(tls)).is_ok());
            assert!(otlp_exporter(
                &local("g")
                    .with_protocol(Protocol::Grpc)
                    .with_tls(TlsConfig {
                        ca_cert_pem: Some("x".into()),
                        ..TlsConfig::default()
                    })
            )
            .is_ok());
            for bad in [insecure, missing] {
                let err = otlp_exporter(&grpc.clone().with_tls(bad)).unwrap_err();
                assert_eq!(err.code(), ErrorCode::Config);
            }
            let bad_cert = TlsConfig {
                client_cert_path: Some("/nonexistent/c.pem".into()),
                client_key_path: Some("/nonexistent/c.key".into()),
                ..TlsConfig::default()
            };
            let err = otlp_exporter(&grpc.clone().with_tls(bad_cert)).unwrap_err();
            assert_eq!(err.code(), ErrorCode::Config);
        } else {
            let err = otlp_exporter(&grpc.clone().with_tls(tls)).unwrap_err();
            assert!(err.message().contains("otlp-tls"), "{err}");
        }
    }

    // The exporter plugs into init_tracing_with.
    let handle = init_tracing_with(
        local("otlp").with_endpoint("http://127.0.0.1:9"),
        otlp_exporter,
    )
    .unwrap();
    handle.shutdown().await.unwrap();
}

#[tokio::test(start_paused = true)]
async fn memory_query_client() {
    let exp = MemorySpanExporter::new();
    let handle = exp.init(local("api")).unwrap();
    let tracer = handle.tracer("t", None);
    with_span(
        "root",
        SpanOptions::default()
            .tracer(tracer.clone())
            .attribute(KeyValue::new("run", "r1")),
        async {
            with_span(
                "db",
                SpanOptions::default()
                    .tracer(tracer.clone())
                    .attribute(KeyValue::new("service.name", "postgres")),
                async { Ok::<_, Error>(()) },
            )
            .await
        },
    )
    .await
    .unwrap();
    span_in(&handle, "second", vec![]).await;
    handle.force_flush(None).await.unwrap();
    let q = exp.query();
    assert_eq!(q.list_services().await.unwrap(), ["api", "postgres"]);
    assert_eq!(q.list_operations("api").await.unwrap(), ["root", "second"]);
    let hits: Vec<TraceSummary> = q.search_traces(&TraceSearchQuery::default()).await.unwrap();
    assert_eq!(hits.len(), 2);
    let tagged = q
        .search_traces(&TraceSearchQuery::default().tag("run", "r1").limit(1))
        .await
        .unwrap();
    assert_eq!(tagged.len(), 1);
    assert_eq!(tagged[0].span_count, 2);
    let deps = q
        .get_dependencies(DependencyOptions::default())
        .await
        .unwrap();
    assert_eq!(deps.len(), 1);
    assert_eq!(
        (
            deps[0].parent.as_str(),
            deps[0].child.as_str(),
            deps[0].call_count
        ),
        ("api", "postgres", 1)
    );
    let id = tagged[0].trace_id.clone();
    let trace = q.get_trace(&id.to_uppercase()).await.unwrap().unwrap();
    assert_eq!(trace.spans.len(), 2);
    assert!(q
        .get_trace("00000000000000000000000000000001")
        .await
        .unwrap()
        .is_none());
    assert_eq!(
        q.get_trace("zz").await.unwrap_err().code(),
        ErrorCode::Validation
    );
    let waited = q
        .wait_for_trace(&id, WaitForTraceOptions::default().min_spans(2))
        .await
        .unwrap();
    assert_eq!(waited.trace_id, id);
    let err = q
        .wait_for_trace(
            &id,
            WaitForTraceOptions::default()
                .min_spans(3)
                .timeout(Duration::from_secs(2))
                .interval(Duration::from_millis(100)),
        )
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Timeout);
    assert_eq!(exp.span_data().len(), 3);
    exp.clear();
    assert!(exp.spans().is_empty());
    handle.shutdown().await.unwrap();
}

#[tokio::test]
async fn sampler_override_and_extra_processors() {
    // A sampler override replaces config.sampler.
    let exp = MemorySpanExporter::new();
    let e = exp.clone();
    let handle = init_tracing_with_sampler(
        local("s"),
        move |_| Ok(e),
        opentelemetry_sdk::trace::Sampler::AlwaysOff,
    )
    .unwrap();
    span_in(&handle, "dropped", vec![]).await;
    handle.force_flush(None).await.unwrap();
    assert!(exp.spans().is_empty());
    handle.shutdown().await.unwrap();

    // Extra span processors see every span; extra propagators satisfy `Other` names.
    let exp = MemorySpanExporter::new();
    let extra = MemorySpanExporter::new();
    let options = PipelineOptions::new()
        .with_span_processor(opentelemetry_sdk::trace::SimpleSpanProcessor::new(
            extra.clone(),
        ))
        .with_propagator("datadog", Box::new(B3Propagator::single()))
        .with_sampler(opentelemetry_sdk::trace::Sampler::AlwaysOn);
    let text = format!("{options:?}");
    assert!(
        text.contains("datadog") && text.contains("AlwaysOn"),
        "{text}"
    );
    let e = exp.clone();
    let config = local("p").with_propagators(vec![PropagatorKind::Other("datadog".into())]);
    let handle = init_tracing_with_pipeline(config, move |_| Ok(e), options).unwrap();
    span_in(&handle, "both", vec![]).await;
    handle
        .force_flush(Some(Duration::from_secs(5)))
        .await
        .unwrap();
    assert_eq!(exp.spans().len(), 1);
    assert_eq!(extra.spans().len(), 1);
    assert_eq!(extra.spans()[0].name, "both");
    handle.shutdown().await.unwrap();
    for _ in 0..200 {
        if extra.shutdown_calls() == 1 {
            break;
        }
        tokio::time::sleep(Duration::from_millis(5)).await;
    }
    assert_eq!(extra.shutdown_calls(), 1);
    let default = PipelineOptions::default();
    assert!(default.sampler.is_none() && default.span_processors.is_empty());
}

